// Pass-barrier decisions of the replay layer (nvn_mtl.m bar_r_begin / bar_draw / enc_r_end, DM_NVN_BARRIER, DM_NVN_PASSGPU_SERIAL), checked through their counters
// with the Metal validation layer on (MTL_DEBUG_LAYER=1). Real Metal 4 render encoders on an 8x8 target; no draw is issued (bar_draw only places barriers), so programs
// are bare NvProg objects with hand-made reflection. Expectations are written by hand from the rules in nvn_mtl.m, not generated by the implementation.
// A GPU race test is not attempted: removing a barrier doesn't reliably fail on this GPU, so it would have no negative control.
#include "../nvn/nvn_mtl.m"
void *front_metal_layer(void) { return NULL; }
module_t *module_of(const void *p) { (void)p; return NULL; }
module_t g_mod[MAX_MOD]; int g_nmod;
void svc_thread_dump(void) {}
uint64_t now_ns(void) { return bp_now(); }
static int fail, count;
#define EXPECT(name, want, got) do { long long w_ = (long long)(want), g_ = (long long)(got); count++; printf("%s: want %lld, got %lld %s\n", name, w_, g_, w_ == g_ ? "✓" : "✗"); fail += w_ != g_; } while (0)
static const MTLStages k_open = MTLStageAll & ~BAR_VTX;   // an end barrier that leaves later vertex stages free
// Program kinds: binding kind (0 = none) and rw of the one binding of the vertex (stage 0) or fragment (stage 1) shader
static NvProg *prog(int stage, int kind, int rw) {
    NvProg *p = [NvProg new]; p->sh[0] = [NvShader new]; p->sh[1] = [NvShader new]; p->sh[1]->stage = 1;
    if (kind) { NvShader *s = p->sh[stage]; s->rf.nb = 1; s->rf.b[0].kind = (uint8_t)kind; s->rf.b[0].rw = (uint8_t)rw; }
    return p;
}
static RPD *g_rp;
static void zero(void) { g_bar_nfree = g_bar_nlazy = g_bar_ntex = g_bar_nvw = g_bar_nwr = g_bar_nwend = 0; g_bar_last_end = 0; g_enc_wrote = 0; }
// One render pass: open, bar_draw for each program given (NULL = a clear-only pass), close
static void pass(NvProg *a, NvProg *b) { RENC e = enc_r_begin(g_rp); if (a) bar_draw(e, a); if (b) bar_draw(e, b); enc_r_end(e); }
int main(void) { setvbuf(stdout, NULL, _IONBF, 0); @autoreleasepool {
    mtl_init();   // runs bar_init; the test then sets the level itself, so the shell's DM_NVN_BARRIER or DM_NVN_PASSGPU_SERIAL can't change the outcome
    MTLTextureDescriptor *td = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:8 height:8 mipmapped:NO];
    td.usage = MTLTextureUsageRenderTarget; td.storageMode = MTLStorageModePrivate;
    id<MTLTexture> rt = [g_dev newTextureWithDescriptor:td]; res_add(rt); res_commit();
    g_rp = [RPD new]; g_rp.colorAttachments[0].texture = rt; g_rp.colorAttachments[0].loadAction = MTLLoadActionClear; g_rp.colorAttachments[0].storeAction = MTLStoreActionStore;
    NvProg *plain = prog(0, 0, 0), *vtex = prog(0, NVN_RB_TEX, 0), *fwrite = prog(1, NVN_RB_IMG, 0), *vbuf = prog(0, NVN_RB_SBUFP, 0), *vwrite = prog(0, NVN_RB_SBUFP, 1);

    // Level 1 (the default)
    g_bar_ser = 0; g_bar_lv = 1; zero();
    mtl_sub_begin();
    pass(plain, NULL);
    EXPECT("level 1, P1 plain: opens with vertex free", 1, g_bar_nfree); EXPECT("P1: no lazy barrier", 0, g_bar_nlazy);
    EXPECT("P1: end leaves later vertex stages free", k_open, g_bar_last_end); EXPECT("P1: no encoder wrote memory", 0, g_bar_nwend);
    pass(vtex, vtex);
    EXPECT("P2 vertex texture read: opens with vertex free", 2, g_bar_nfree); EXPECT("P2: one lazy barrier for two texture-reading draws", 1, g_bar_nlazy);
    EXPECT("P2: counted as a texture read", 1, g_bar_ntex); EXPECT("P2: end leaves vertex free", k_open, g_bar_last_end);
    pass(fwrite, NULL);
    EXPECT("P3 fragment writes memory: opens with vertex free", 3, g_bar_nfree); EXPECT("P3: one draw writing memory", 1, g_bar_nwr);
    EXPECT("P3: no lazy barrier (vertex reads nothing)", 1, g_bar_nlazy);
    EXPECT("P3: the writer's end holds every later stage, vertex included", MTLStageAll, g_bar_last_end); EXPECT("P3: one encoder wrote memory", 1, g_bar_nwend);
    pass(NULL, NULL);
    EXPECT("P4 clear-only after the writer: opens with vertex free (no one-shot full start)", 4, g_bar_nfree);
    EXPECT("P4: end leaves vertex free", k_open, g_bar_last_end); EXPECT("P4: still one writer", 1, g_bar_nwend);
    pass(NULL, NULL);
    EXPECT("P5 second clear-only: opens with vertex free", 5, g_bar_nfree); EXPECT("P5: end leaves vertex free", k_open, g_bar_last_end); EXPECT("P5: still one writer", 1, g_bar_nwend);
    pass(plain, NULL);
    EXPECT("P6 plain after writer + two clears: opens with vertex free", 6, g_bar_nfree); EXPECT("P6: end leaves vertex free", k_open, g_bar_last_end);
    EXPECT("P6: only the writer held vertex at its end", 1, g_bar_nwend);
    pass(vbuf, NULL);   // documents existing behaviour: vertex storage-buffer reads are ordered by writers' end barriers and the full end of compute / copy encoders
    EXPECT("P7 vertex storage-buffer read: no lazy barrier", 1, g_bar_nlazy);
    pass(vwrite, NULL);
    EXPECT("P8 vertex writes memory: lazy barrier before the draw", 2, g_bar_nlazy); EXPECT("P8: counted as a vertex write", 1, g_bar_nvw);
    EXPECT("P8: draws writing memory", 2, g_bar_nwr); EXPECT("P8: end holds every later stage", MTLStageAll, g_bar_last_end); EXPECT("P8: two encoders wrote memory", 2, g_bar_nwend);
    uint64_t f = mtl_sub_commit();
    EXPECT("level 1 submission completes", 1, mtl_wait(f, 5000000000ull)); EXPECT("level 1 submission: no command buffer error", 0, mtl_last_commit_error());

    // Level 0: full barriers everywhere
    g_bar_ser = 0; g_bar_lv = 0; zero();
    mtl_sub_begin();
    pass(vtex, NULL);
    EXPECT("level 0: no pass opens with vertex free", 0, g_bar_nfree); EXPECT("level 0: no lazy barrier", 0, g_bar_nlazy);
    EXPECT("level 0: end holds every later stage", MTLStageAll, g_bar_last_end);
    f = mtl_sub_commit();
    EXPECT("level 0 submission completes", 1, mtl_wait(f, 5000000000ull)); EXPECT("level 0 submission: no command buffer error", 0, mtl_last_commit_error());

    // DM_NVN_PASSGPU_SERIAL pins the level at 0, whatever g_bar_lv says (a DM_NVN_UB write included)
    g_bar_ser = 1; g_bar_lv = 1; zero();
    EXPECT("serial pin: effective level 0", 0, bar_lv());
    mtl_sub_begin();
    pass(fwrite, NULL);
    EXPECT("serial pin: no pass opens with vertex free", 0, g_bar_nfree); EXPECT("serial pin: bar_draw does nothing", 0, g_bar_nwr);
    EXPECT("serial pin: end holds every later stage", MTLStageAll, g_bar_last_end);
    f = mtl_sub_commit();
    EXPECT("serial submission completes", 1, mtl_wait(f, 5000000000ull)); EXPECT("serial submission: no command buffer error", 0, mtl_last_commit_error());

    // The game's own NVN barriers (OP_BARRIER → bar_game) are counted only, by what orders their earlier work before a level-1 pass's vertex stage (behaviour doesn't change)
    g_bar_ser = 0; g_bar_lv = 1;
    g_bar_gn = g_bar_gopen = g_bar_gcov = g_bar_gtex_open = g_bar_gmid = g_bar_gvtx_mid = g_bar_gtex_mid = g_bar_gfrag_mid = g_bar_gtail = 0; memset(g_bar_gbit, 0, sizeof g_bar_gbit);
    g_bar_gpend = g_bar_gunc = g_bar_gdraw = 0; memset(g_bar_gdn, 0, sizeof g_bar_gdn);
    mtl_sub_begin();
    bar_game(0x1); pass(NULL, NULL);   // the serial section's last encoder ended with the full barrier: everything before it is ordered
    EXPECT("full render end (level 0) → barrier → pass: not uncovered", 0, g_bar_gopen); EXPECT("... counted as ordered by a full end barrier", 1, g_bar_gcov);
    pass(plain, NULL);   // a render encoder whose end leaves later vertex stages free: its work is not ordered before the next pass's vertex stage
    g_enc = nil; bar_game(0x21);   // order primitives + invalidate shader, between passes
    EXPECT("game barrier: counted", 2, g_bar_gn); EXPECT("game barrier: bit 0 counted", 2, g_bar_gbit[0]); EXPECT("game barrier: bit 5 counted", 1, g_bar_gbit[5]);
    EXPECT("game barrier between passes is not mid-pass", 0, g_bar_gmid);
    pass(NULL, NULL);
    EXPECT("vertex-free render end → barrier → pass start that leaves vertex open: uncovered", 1, g_bar_gopen); EXPECT("the pass start consumes the pending bits", 0, g_bar_gpend);
    bar_game(0x10); pass(NULL, NULL);   // texture invalidate only: covered at a pass start
    EXPECT("texture invalidate only: not counted as uncovered", 1, g_bar_gopen); EXPECT("texture invalidate only: counted in its own class", 1, g_bar_gtex_open);
    EXPECT("texture invalidate: consumed", 0, g_bar_gpend);
    bar_game(0x1); { CENC ce = enc_c_begin(NULL); enc_c_end(ce); } pass(NULL, NULL);
    EXPECT("barrier → compute encoder (full start and end) → pass: not uncovered", 1, g_bar_gopen);
    bar_game(0x8); (void)blit(); enc_b_end(g_blit); g_blit = nil; pass(NULL, NULL);
    EXPECT("barrier → copy encoder (full start and end) → pass: not uncovered", 1, g_bar_gopen);
    EXPECT("barriers before a compute or copy encoder are dropped there: the pass start counts nothing (ordered-by-full-end count unchanged)", 1, g_bar_gcov);
    pass(plain, NULL); { CENC ce = enc_c_begin(NULL); enc_c_end(ce); } bar_game(0x1); pass(NULL, NULL);
    EXPECT("dispatch → barrier → pass: the compute encoder's full end orders everything before the barrier, not uncovered", 1, g_bar_gopen);
    pass(plain, NULL); (void)blit(); bar_game(0x1); enc_b_end(g_blit); g_blit = nil; pass(NULL, NULL);
    EXPECT("copy encoder open → barrier → pass: its full end orders everything before the barrier, not uncovered", 1, g_bar_gopen);
    pass(fwrite, NULL); bar_game(0x1); pass(NULL, NULL);
    EXPECT("encoder that wrote memory (full end) → barrier → pass: not uncovered", 1, g_bar_gopen);
    EXPECT("dispatch, open copy encoder, writer: each counted as ordered by a full end barrier", 4, g_bar_gcov);
    { CENC ce = enc_c_begin(NULL); enc_c_end(ce); }
    { RENC h = [g_cb renderCommandEncoderWithDescriptor:g_rp]; [h barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageAll visibilityOptions:MTL4VisibilityOptionDevice]; enc_host_r_end(h); }
    bar_game(0x1); pass(NULL, NULL);
    EXPECT("dispatch → host render pass (full start, vertex-free end) → barrier → pass: uncovered", 2, g_bar_gopen);
    bar_game(0x80); pass(NULL, NULL);   // zcull only
    EXPECT("zcull only: not uncovered", 2, g_bar_gopen); EXPECT("zcull only: not texture", 1, g_bar_gtex_open); EXPECT("zcull only: not vertex-relevant", 4, g_bar_gcov);
    { RENC e = enc_r_begin(g_rp); g_enc = e;   // inside an open render encoder: mid-pass once a draw follows, at either level
      bar_game(0x2); EXPECT("fragment ordering in an open encoder, no draw after it yet: not mid-pass yet", 0, g_bar_gmid);
      bar_draw(e, plain); EXPECT("a draw follows: mid-pass", 1, g_bar_gmid); EXPECT("mid-pass fragment ordering: its class", 1, g_bar_gfrag_mid);
      bar_game(0x10); bar_draw(e, plain); EXPECT("mid-pass texture invalidate: mid-pass", 2, g_bar_gmid); EXPECT("mid-pass texture invalidate: its class", 1, g_bar_gtex_mid);
      bar_game(0x20); bar_draw(e, plain); EXPECT("mid-pass shader invalidate: mid-pass", 3, g_bar_gmid); EXPECT("mid-pass shader invalidate: vertex-relevant class", 1, g_bar_gvtx_mid);
      EXPECT("mid-pass barriers leave nothing pending", 0, g_bar_gpend);
      bar_game(0x1);   // after the encoder's last draw
      enc_r_end(e); g_enc = nil;
      EXPECT("barrier after an encoder's last draw: not mid-pass", 3, g_bar_gmid); EXPECT("barrier after an encoder's last draw: not in the vertex-relevant mid-pass class", 1, g_bar_gvtx_mid);
      EXPECT("barrier after an encoder's last draw: counted on its own", 1, g_bar_gtail); EXPECT("... and its bits wait for the next pass start", 0x1, g_bar_gpend); }
    pass(NULL, NULL);
    EXPECT("barrier after the last draw of an encoder ending with vertex free → next pass start: uncovered", 3, g_bar_gopen);
    { RENC e = enc_r_begin(g_rp); g_enc = e; bar_draw(e, fwrite); bar_game(0x1); enc_r_end(e); g_enc = nil; } pass(NULL, NULL);
    EXPECT("barrier after the last draw of an encoder that wrote memory (full end) → next pass start: not uncovered", 3, g_bar_gopen);
    EXPECT("... ordered by that encoder's full end barrier", 5, g_bar_gcov);
    EXPECT("barriers after the last draw: never mid-pass", 3, g_bar_gmid); EXPECT("barriers after the last draw: two", 2, g_bar_gtail);
    g_bar_lv = 0; bar_game(0x1); pass(NULL, NULL);
    EXPECT("level 0: a full pass start is not counted as uncovered", 3, g_bar_gopen); EXPECT("level 0: the pass start still clears the pending bits", 0, g_bar_gpend);
    EXPECT("game barriers counted in all", 16, g_bar_gn);
    f = mtl_sub_commit();
    EXPECT("game-barrier submission completes", 1, mtl_wait(f, 5000000000ull)); EXPECT("game-barrier submission: no command buffer error", 0, mtl_last_commit_error());
    g_bar_lv = 1;
}
    printf("t_bar: %d checks, %d failed\n", count, fail); return fail != 0;
}
